export function translateText(value, language = 'en') {
  if (language !== 'en' || typeof value !== 'string') return value;
  const leading = value.match(/^\s*/)[0], trailing = value.match(/\s*$/)[0], text = value.trim();
  if (Object.hasOwn(COPY, text)) return leading + COPY[text] + trailing;
  const rules = [
    [/^AI 预计：(黑棋|白棋)领先 ([\d.]+) 目$/, (_, c, n) => `AI prediction: ${c === '黑棋' ? 'Black' : 'White'} leads by ${n} points`],
    [/^(黑棋|白棋)盘面多 ([\d.]+) 目$/, (_, c, n) => `Area count: ${c === '黑棋' ? 'Black' : 'White'} leads by ${n} points`],
    [/^黑棋：([\d]+) 子 \+ ([\d]+) 空；白棋：([\d]+) 子 \+ ([\d]+) 空 \+ ([-\d.]+) 贴目。中立点 ([\d]+)。$/, (_, b, bt, w, wt, k, n) => `Black: ${b} stones + ${bt} territory; White: ${w} stones + ${wt} territory + ${k} komi. Neutral: ${n}.`],
    [/^标记死子：黑 (\d+)，白 (\d+)$/, (_, b, w) => `Marked dead: ${b} black, ${w} white`],
    [/^([A-T]\d+) · (黑棋|白棋|空点)( · 死子)?$/, (_, p, c, dead) => `${p} · ${c === '黑棋' ? 'Black' : c === '白棋' ? 'White' : 'Empty'}${dead ? ' · dead' : ''}`],
    [/^执白 · 贴 ([-\d.]+) 目$/, (_, n) => `White · ${n} komi`],
    [/^轮到(黑棋|白棋) · 自由摆谱$/, (_, c) => `${c === '黑棋' ? 'Black' : 'White'} to move · analysis`],
    [/^第 (\d+) 手时$/, (_, n) => `After move ${n}`],
    [/^(黑棋|白棋)预计领先 ([\d.]+) 目$/, (_, c, n) => `${c === '黑棋' ? 'Black' : 'White'} leads by about ${n} points`],
    [/^回到第 (\d+) 手，重新思考。$/, (_, n) => `Back to move ${n}. Think it through again.`],
    [/^本地 (CPU|GPU) 搜索 · 分析始终使用全力模型$/, (_, d) => `Local ${d} search · full-strength analysis`],
    [/^本地 KataGo · (CPU|GPU)$/, (_, d) => `Local KataGo · ${d}`],
    [/^围棋棋盘，光标位于 (.+)。方向键移动，回车落子。$/, (_, p) => `Go board. Cursor at ${p}. Use arrow keys and Enter.`],
    [/^(黑棋|白棋)认输，KataGo 获胜。$/, (_, c) => `${c === '黑棋' ? 'Black' : 'White'} resigns. KataGo wins.`],
    [/^KataGo 推荐：(.+) · 搜索 (.+) 次$/, (_, p, n) => `KataGo suggests ${translateText(p)} · ${n} visits`],
    [/^后续 AI 落子使用：(.+)。$/, (_, rank) => `Subsequent AI moves use: ${translateText(rank)}.`],
    [/^(人类棋风模拟 · )?用时 ([\d.]+) 秒 · 局面评估仅供参考。$/, (_, human, n) => `${human ? 'Human-style play · ' : ''}${n} sec · evaluation is an estimate.`],
    [/^全力分析 · 可以考虑 (.+)$/, (_, p) => `Full-strength analysis · consider ${translateText(p)}`],
    [/^参考变化：(.+)$/, (_, pv) => `Variation: ${pv.replaceAll('停一手', 'pass')}`],
    [/^KataGo 着法被规则检查拒绝：(.+)$/, (_, e) => `KataGo move rejected: ${translateText(e)}`],
  ];
  for (const [pattern, format] of rules) if (pattern.test(text)) return leading + text.replace(pattern, format) + trailing;
  if (/^盘面数子：/.test(text)) return text.replace('盘面数子：黑棋 ', 'Board area: Black ').replace('，白棋 ', ', White ').replace('（含贴目 ', ' (including komi ').replace('）。', '). ').replace('盘面持平。', 'The board count is tied.').replace('黑棋盘面多 ', 'Black has ').replace('白棋盘面多 ', 'White has ').replace(' 目。', ' more points.');
  return value.replace(/(\d+)(级|段)（近似）/g, (_, n, rank) => `${n} ${rank === '级' ? 'kyu' : 'dan'} (approx.)`).replace('KataGo · 全力', 'KataGo · full strength').replaceAll('停一手', 'Pass');
}

let language = 'zh';
export function getLanguage() { return language; }
export function initLanguage({ initialLanguage, onChange } = {}) {
  try { language = initialLanguage || localStorage.getItem('shiro-go-language') || (navigator.language.startsWith('zh') ? 'zh' : 'en'); } catch { language = initialLanguage || 'zh'; }
  const texts = new WeakMap(), attributes = new WeakMap();
  const bind = (node, map, read, write) => {
    const current = read(); let record = map.get(node);
    if (!record || current !== record.output) record = { source: current, output: current };
    const output = translateText(record.source, language);
    record.output = output; map.set(node, record);
    if (current !== output) write(output);
  };
  const localize = () => {
    document.documentElement.lang = language === 'en' ? 'en' : 'zh-CN';
    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    while (walker.nextNode()) {
      const node = walker.currentNode;
      if (node.parentElement?.closest('script,style,[data-no-translate]')) continue;
      bind(node, texts, () => node.nodeValue, value => { node.nodeValue = value; });
    }
    for (const element of document.querySelectorAll('[aria-label],[title],[placeholder],optgroup[label]')) {
      let records = attributes.get(element); if (!records) { records = new Map(); attributes.set(element, records); }
      for (const name of ['aria-label', 'title', 'placeholder', 'label']) if (element.hasAttribute(name)) {
        let record = records.get(name); const current = element.getAttribute(name);
        if (!record || current !== record.output) record = { source: current, output: current };
        record.output = translateText(record.source, language); records.set(name, record);
        if (current !== record.output) element.setAttribute(name, record.output);
      }
    }
    document.title = language === 'en' ? 'Shiro Go · Local KataGo' : '弈间 · KataGo 围棋';
    const select = document.getElementById('language'); if (select) select.value = language;
  };
  const observer = new MutationObserver(localize);
  observer.observe(document.body, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: ['aria-label', 'title', 'placeholder', 'label'] });
  document.getElementById('language')?.addEventListener('change', event => {
    language = event.target.value === 'en' ? 'en' : 'zh';
    try { localStorage.setItem('shiro-go-language', language); } catch {}
    onChange?.(language);
    localize();
  });
  localize();
  return { refresh: localize, get language() { return language; } };
}
